university.sql:
SELECT StudID, StudName
FROM student NATURAL JOIN takes
WHERE Grade IS NULL;

SELECT StudID, StudName, count(CourseID), count(Grade)
FROM takes NATURAL JOIN student
GROUP BY StudID;

SELECT InstID, InstName
FROM instructor WHERE InstID IN (SELECT InstID
FROM teaches WHERE Semester = 'Spring' AND StudyYear = '2009');

university.original:
drop view if exists courseTaken;
create view courseTaken (StudID, NumCourses) as
Select StudID, Count(CourseID)
from student natural left join takes
group by studID;

select StudID, StudName
from student natural join courseTaken
where NumCourses > (Select avg(NumCourses)
	from courseTaken);

cinema.sql:
SELECT tid
FROM ticket
WHERE price > 120;

SELECT tid
FROM ticket NATURAL JOIN projection NATURAL JOIN movie
WHERE genre = 'Sci-Fi';

SELECT mid, title, genre, sum(price) AS income
FROM movie NATURAL JOIN projection NATURAL JOIN ticket
GROUP BY mid;

cinema.original:
Create view incomeview as
select mid, title, genre, sum(price) as income
from movie natural join projection natural join ticket
group by mid;
set @aveinc = (Select avg(income) from incomeview);
select mid, title, genre, income
from incomeview
group by mid
having income > @aveinc;

drop function if exists reservedSeats;
create function
reservedSeats(ridn int(3), pdaten date) returns int
return
	(Select count(tid) as reservations
    from Projection natural join ticket
    where rid = ridn and pdate = pdaten);

Select rid, reservedSeats(rid, pdate) as reserved_seats
from projection where pdate = '2025-12-19';

Select pid, count(sno)-reservedSeats(rid, pdate) as empty_seats
from projection natural join seat
group by pid;

takeaway.sql:
SELECT catId, catName, max(unitPrice) AS highest_price
FROM FoodCategory NATURAL LEFT JOIN FoodItem
GROUP BY catId;

