drop function if exists total_cost_for_customer;
create function
total_cost_for_customer(v_custNo int) returns int
return
  (select sum(unitPrice * quantity)
  from FoodOrder natural join Orderline
  where custNo = v_custNo);

select custNo, total_cost_for_customer(custNo) as total_cost from Customer;

busservice.sql:
SELECT tripID, count(CNO) AS count_passengers
FROM Trip NATURAL LEFT JOIN TripPassengers
GROUP BY tripID;

DROP TRIGGER IF EXISTS Trip_Before_Insert;
CREATE TRIGGER Trip_Before_Insert
BEFORE INSERT ON Trip FOR EACH ROW
WHEN NEW.fromStation = NEW.toStation
BEGIN
    SELECT RAISE(ABORT, 'fromStation and toStation must be different');
END;

busservice.original:
DROP TRIGGER IF EXISTS  Trip_Before_Insert;
DELIMITER $$
CREATE TRIGGER Trip_Before_Insert
BEFORE INSERT ON Trip  FOR EACH ROW
IF NEW.fromStation = NEW.toStation
THEN  SIGNAL SQLSTATE 'HY000' SET MYSQL_ERRNO = 1525,
      MESSAGE_TEXT = 'fromStation and toStation must be different';
END IF;
$$
DELIMITER ;

